"""Role-based access guard built with Reflex.

Access to protected pages is enforced with page ``on_load`` event guards that
redirect unauthenticated or unauthorized visitors. Seeded credentials and the
active session live entirely in backend-only state (attributes prefixed with
``_``) so that plaintext passwords are never sent to the browser.
"""

from __future__ import annotations

import hashlib
import hmac
import secrets

import reflex as rx


# --------------------------------------------------------------------------- #
# Password hashing helpers (backend only, never exposed to the client).
# --------------------------------------------------------------------------- #
_PBKDF2_ITERATIONS = 200_000
_SALT_BYTES = 16


def _hash_password(password: str) -> tuple[str, str]:
    """Return ``(salt_hex, digest_hex)`` for a plaintext password."""
    salt = secrets.token_bytes(_SALT_BYTES)
    digest = hashlib.pbkdf2_hmac(
        "sha256", password.encode("utf-8"), salt, _PBKDF2_ITERATIONS
    )
    return salt.hex(), digest.hex()


def _verify_password(password: str, salt_hex: str, expected_hex: str) -> bool:
    """Constant-time check of a plaintext password against the stored hash."""
    salt = bytes.fromhex(salt_hex)
    digest = hashlib.pbkdf2_hmac(
        "sha256", password.encode("utf-8"), salt, _PBKDF2_ITERATIONS
    )
    return hmac.compare_digest(digest.hex(), expected_hex)


def _seed_users() -> dict[str, dict[str, str]]:
    """Build the two seeded user accounts with locally-salted password hashes."""
    seeded: dict[str, dict[str, str]] = {}
    for username, password, role in (
        ("admin", "s3cure-admin-pw", "admin"),
        ("alice", "s3cure-user-pw", "user"),
    ):
        salt_hex, digest_hex = _hash_password(password)
        seeded[username] = {"salt": salt_hex, "hash": digest_hex, "role": role}
    return seeded


# Seeded once at import time; plaintext passwords go no further than here.
_SEEDED_USERS = _seed_users()


# --------------------------------------------------------------------------- #
# Application state.
# --------------------------------------------------------------------------- #
class State(rx.State):
    """Holds seeded credentials, the active session, and authorization vars."""

    # --- Backend-only (prefixed with ``_`` -> never serialized to the client) ---
    _users: dict[str, dict[str, str]] = _SEEDED_USERS
    _auth_user: str | None = None
    _auth_role: str | None = None

    # --- Frontend-visible form fields ---
    login_username: str = ""
    login_password: str = ""
    login_error: str = ""

    # --- Computed authorization vars (derived from backend-only state) ---
    @rx.var
    def is_authenticated(self) -> bool:
        return self._auth_user is not None

    @rx.var
    def is_admin(self) -> bool:
        return self._auth_role == "admin"

    @rx.var
    def auth_username(self) -> str:
        return self._auth_user or ""

    @rx.var
    def auth_role(self) -> str:
        return self._auth_role or ""

    # --- Page-load guards ---
    def check_auth(self):
        """Guard for any authenticated page: redirect to /login if not signed in."""
        if not self.is_authenticated:
            return rx.redirect("/login")

    def check_admin(self):
        """Guard for the admin page: redirect to /login or /forbidden as needed."""
        if not self.is_authenticated:
            return rx.redirect("/login")
        if not self.is_admin:
            return rx.redirect("/forbidden")

    # --- Authentication actions ---
    def login(self):
        """Validate credentials and establish the session."""
        record = self._users.get(self.login_username)
        if record and _verify_password(
            self.login_password, record["salt"], record["hash"]
        ):
            self._auth_user = self.login_username
            self._auth_role = record["role"]
            self.login_error = ""
            self.login_password = ""
            self.login_username = ""
            return rx.redirect("/dashboard")

        # Invalid credentials: stay on /login and surface an error message.
        self.login_error = "Invalid credentials"
        self.login_password = ""
        return None

    def logout(self):
        """Clear the session and return to /login."""
        self._auth_user = None
        self._auth_role = None
        self.login_error = ""
        self.login_password = ""
        self.login_username = ""
        return rx.redirect("/login")


# --------------------------------------------------------------------------- #
# Pages.
# --------------------------------------------------------------------------- #
@rx.page(route="/login", title="Login")
def login_page() -> rx.Component:
    """Public login page."""
    return rx.center(
        rx.card(
            rx.vstack(
                rx.heading("Login", size="6"),
                rx.form(
                    rx.vstack(
                        rx.input(
                            placeholder="Username",
                            value=State.login_username,
                            on_change=State.set_login_username,
                            name="username",
                            size="3",
                        ),
                        rx.input(
                            type="password",
                            placeholder="Password",
                            value=State.login_password,
                            on_change=State.set_login_password,
                            name="password",
                            size="3",
                        ),
                        rx.button("Submit", type="submit", size="3", width="100%"),
                        spacing="3",
                    ),
                    on_submit=State.login,
                ),
                rx.cond(
                    State.login_error != "",
                    rx.text(State.login_error, color="red", size="2"),
                ),
                spacing="4",
                align="center",
            ),
            size="3",
        ),
        min_height="85vh",
    )


@rx.page(route="/dashboard", title="Dashboard", on_load=State.check_auth)
def dashboard_page() -> rx.Component:
    """Protected dashboard available to any authenticated user."""
    return rx.container(
        rx.vstack(
            rx.heading("Dashboard", size="8"),
            rx.text("Username: ", rx.code(State.auth_username)),
            rx.text("Role: ", rx.code(State.auth_role)),
            rx.button("Logout", on_click=State.logout),
            spacing="4",
            align="start",
        ),
        py="8",
    )


@rx.page(route="/admin", title="Admin Panel", on_load=State.check_admin)
def admin_page() -> rx.Component:
    """Admin-only page."""
    return rx.container(
        rx.vstack(
            rx.heading("Admin Panel", size="8"),
            rx.text("Welcome, ", rx.code(State.auth_username), " (admin)"),
            rx.button("Logout", on_click=State.logout),
            spacing="4",
            align="start",
        ),
        py="8",
    )


@rx.page(route="/forbidden", title="Access Denied")
def forbidden_page() -> rx.Component:
    """Public forbidden page."""
    return rx.center(
        rx.vstack(
            rx.heading("Access Denied", size="8"),
            rx.link(rx.button("Go to login"), href="/login"),
            spacing="4",
            align="center",
        ),
        min_height="85vh",
    )


@rx.page(route="/", title="Role Guard")
def index_page() -> rx.Component:
    """Root redirects to the dashboard (which itself guards access)."""
    return rx.center(
        rx.spinner(),
        min_height="85vh",
    )


def _index_redirect():
    return rx.redirect("/dashboard")


app = rx.App()

